	static boolean isCorpbane(String weaponName)
	{
		if (weaponName == null)
		{
			return false;
		}
		String n = weaponName.toLowerCase(Locale.ROOT);
		return isFang(weaponName) || n.contains("halberd") || (n.contains("spear") && !n.startsWith("blue moon spear"));
	}

